materials.content:
:root {
  --warna-utama: #1f6f4a;
  --warna-latar: #f6f7f2;
  --warna-teks: #1b1d1a;
  --jarak: 1rem;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  line-height: 1.6;
  color: var(--warna-teks);
  background: var(--warna-latar);
}

a { color: var(--warna-utama); }

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--jarak);
}
.header nav a { margin-left: var(--jarak); text-decoration: none; }
.logo { font-weight: 700; text-decoration: none; }

.hero { padding: 4rem var(--jarak); max-width: 40rem; margin: 0 auto; }
.hero h1 { font-size: 2.25rem; line-height: 1.15; margin: 0 0 var(--jarak); }

.tombol {
  display: inline-block;
  padding: 0.75rem 1.5rem;
  border-radius: 999px;
  background: var(--warna-utama);
  color: white;
  text-decoration: none;
  font-weight: 600;
}

.bagian { padding: 2rem var(--jarak); max-width: 40rem; margin: 0 auto; }

.kartu {
  padding: var(--jarak);
  margin-bottom: var(--jarak);
  background: white;
  border-radius: 1rem;
  box-shadow: 0 2px 8px rgb(0 0 0 / 0.08);
}

.daftar { display: flex; flex-wrap: wrap; gap: 0.5rem; padding: 0; list-style: none; }
.daftar li { padding: 0.25rem 0.75rem; border-radius: 999px; background: white; }

@media (min-width: 48rem) {
  .hero { padding: 6rem var(--jarak); }
  .hero h1 { font-size: 3.25rem; }

  .proyek-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: var(--jarak);
  }
}
